/// Every sound effect in the game (generated by tool/synth_audio.py).
enum Sfx {
  tap('tap'),
  toggleOn('toggle_on'),
  toggleOff('toggle_off'),
  diceShake('dice_shake'),
  diceLand('dice_land'),
  step1('step_1'),
  step2('step_2'),
  step3('step_3'),
  step4('step_4'),
  step5('step_5'),
  step6('step_6'),
  drop('drop'),
  capture('capture'),
  captureWar('capture_war'),
  capturePeace('capture_peace'),
  home('home'),
  win('win'),
  lose('lose'),
  yourTurn('your_turn'),
  chat('chat'),
  reaction('reaction'),

  /// A piece sent home, sad about it: a wobbly little "aww" and a sniffle.
  reactSad('react_sad'),

  /// A piece sent home and not giving up: a whoosh up into a power chord.
  reactAgain('react_again'),

  /// A six: a quick bright sparkle (another roll's coming).
  six('six'),

  /// Someone got all four pieces home and took their place.
  finish('finish'),

  // Cards (Crazy Eights).
  /// A card dealt: a soft flick.
  cardDeal('card_deal'),

  /// A card played onto the pile: a snap.
  cardPlay('card_play'),

  /// A card drawn: a slide.
  cardDraw('card_draw'),

  /// An eight played: a magic swirl as the suit changes.
  cardWild('card_wild'),

  /// Down to one card: a cheeky two-note call.
  lastCard('last_card'),

  // Pool.
  /// The cue's tip on the cue ball: a woody tock.
  poolCue('pool_cue'),

  /// Ball on ball: a bright click.
  poolClick('pool_click'),

  /// A ball off a cushion: a dull thud.
  poolCushion('pool_cushion'),

  /// A ball dropping into a pocket, rattling down.
  poolPocket('pool_pocket'),

  /// The break: the cue ball into the rack.
  poolBreak('pool_break'),

  /// A drawer, menu or panel opening: soft rising bubbles.
  drawer('drawer'),
  purchase('purchase'),

  /// Coins going out: a gift sent (purchase is coins coming in).
  coinsOut('coins_out'),
  teleport('teleport'),
  tick('tick'),
  chessMove('chess_move'),
  chessCapture('chess_capture'),
  chessCheck('chess_check'),

  // The rank hologram reading out stats (played as they animate in).
  holoOn('holo_on'),
  holoBlip1('holo_blip_1'),
  holoBlip2('holo_blip_2'),
  holoBlip3('holo_blip_3'),
  holoBlip4('holo_blip_4'),
  holoTick('holo_tick'),

  // Each tier's aura, far off, looping under the hologram while it's open
  // (loaded when first wanted, not with the rest).
  holoAmbBronze('holo_amb_bronze'),
  holoAmbSilver('holo_amb_silver'),
  holoAmbGold('holo_amb_gold'),
  holoAmbDiamond('holo_amb_diamond'),
  holoAmbLegend('holo_amb_legend'),

  // The Halloween world's music is a soundscape (tool/synth_world_audio.py):
  // these play over its bed, in step with the scene (WorldSoundscape).
  hwNote1('hw_note_1'),
  hwNote2('hw_note_2'),
  hwNote3('hw_note_3'),
  hwNote4('hw_note_4'),
  hwNote5('hw_note_5'),
  hwNote6('hw_note_6'),
  hwRumble1('hw_rumble_1'),
  hwRumble2('hw_rumble_2'),
  hwGhost1('hw_ghost_1'),
  hwGhost2('hw_ghost_2'),
  hwMagic('hw_magic'),
  hwBell('hw_bell'),
  hwOwl('hw_owl'),
  hwThunder1('hw_thunder_1'),
  hwThunder2('hw_thunder_2'),
  hwThunder3('hw_thunder_3'),
  hwCackle('hw_cackle'),
  hwScream('hw_scream'),
  hwDread('hw_dread'),
  hwWhisperLeft('hw_whisper_left'),
  hwWhisperRight('hw_whisper_right'),
  hwMoanLeft('hw_moan_left'),
  hwMoanRight('hw_moan_right'),

  // The Winter world's, in step with its scene (WorldSoundscape): Santa's
  // sleigh bells as he crosses the sky (tool/recorded_sfx.py), gusts of
  // wind and New Year's Eve fireworks (tool/synth_world_audio.py). Loaded
  // in a browser only once the Winter world shows ([GameAudio.warm]).
  wnSleigh('wn_sleigh'),
  wnGust1('wn_gust_1'),
  wnGust2('wn_gust_2'),
  wnFirework1('wn_firework_1'),
  wnFirework2('wn_firework_2');

  const Sfx(this.file);

  final String file;

  /// The hop sound for the [n]th step of a move: climbs a pentatonic
  /// scale so a long move sounds like it's bubbling upward.
  static Sfx step(int n) =>
      const [step1, step2, step3, step4, step5, step6][n % 6];

  /// The hologram's blip for its [n]th readout: climbing through four
  /// pitches as the readouts come up.
  static Sfx holoBlip(int n) =>
      const [holoBlip1, holoBlip2, holoBlip3, holoBlip4][n % 4];
}

enum MusicTrack {
  none(null),
  menu('music/menu.wav'),
  game('music/game.wav'),

  /// The Halloween world's music in place of the menu's: a calm, spooky bed
  /// that the world's sounds play over (see WorldSoundscape).
  halloween('music/halloween.m4a'),

  /// The Birthday world's: "Happy Birthday to You" as a party waltz.
  birthday('music/birthday.m4a'),

  /// The Winter world's: "Silent Night" on a music box, with the world's
  /// sounds over it (see WorldSoundscape).
  winter('music/winter.m4a');

  const MusicTrack(this.asset);

  final String? asset;
}

@immutable
class SoundSettings {
  const SoundSettings({
    this.musicOn = true,
    this.sfxOn = true,
    this.musicVolume = 0.35,
    this.sfxVolume = 0.8,
  });

  final bool musicOn;
  final bool sfxOn;
  final double musicVolume;
  final double sfxVolume;

  SoundSettings copyWith({
    bool? musicOn,
    bool? sfxOn,
    double? musicVolume,
    double? sfxVolume,
  }) {
    return SoundSettings(
      musicOn: musicOn ?? this.musicOn,
      sfxOn: sfxOn ?? this.sfxOn,
      musicVolume: musicVolume ?? this.musicVolume,
      sfxVolume: sfxVolume ?? this.sfxVolume,
    );
  }
}

/// The player's music and sound-effect switches, remembered on device.
class SoundSettingsController extends StateNotifier<SoundSettings> {
  SoundSettingsController(this._prefs)
    : super(
        SoundSettings(
          musicOn: _prefs.getBool('sound.music') ?? true,
          sfxOn: _prefs.getBool('sound.sfx') ?? true,
          musicVolume: _prefs.getDouble('sound.musicVolume') ?? 0.35,
          sfxVolume: _prefs.getDouble('sound.sfxVolume') ?? 0.8,
        ),
      );

  final SharedPreferences _prefs;

  void setMusicOn(bool on) {
    state = state.copyWith(musicOn: on);
    _prefs.setBool('sound.music', on);
  }

  void setSfxOn(bool on) {
    state = state.copyWith(sfxOn: on);
    _prefs.setBool('sound.sfx', on);
  }

  void setMusicVolume(double v) {
    state = state.copyWith(musicVolume: v);
    _prefs.setDouble('sound.musicVolume', v);
  }

  void setSfxVolume(double v) {
    state = state.copyWith(sfxVolume: v);
    _prefs.setDouble('sound.sfxVolume', v);
  }
}

final soundSettingsProvider =
    StateNotifierProvider<SoundSettingsController, SoundSettings>(
      (ref) => SoundSettingsController(ref.watch(sharedPreferencesProvider)),
    );

/// Plays the game's music and sound effects, honoring [SoundSettings].
///
/// Audio runs in the "ambient" style games use: it respects the silent
/// switch and mixes with whatever else is playing. Music pauses while the
/// app is in the background. Every call is fire-and-forget and never
/// throws: a missing audio device must never break gameplay.
class GameAudio {
  GameAudio(this._settings) {
    _lifecycle = AppLifecycleListener(onStateChange: _onLifecycle);
    // A browser plays through WebAudio (one audio context, effects from
    // memory), switched on by the page's first touch.
    if (kIsWeb) {
      WebAudio.instance.preloadOnUnlock([
        for (final sfx in Sfx.values)
          if (!sfx.file.startsWith('holo_amb') && !sfx.file.startsWith('wn_'))
            _effectAsset(sfx),
      ]);
    }
  }

  static String _effectAsset(Sfx sfx) => 'assets/sfx/${sfx.file}.wav';

  SoundSettings _settings;
  late final AppLifecycleListener _lifecycle;

  AudioPlayer? _music;
  final Map<Sfx, Future<AudioPool>> _pools = {};

  /// How long each effect's clip runs, read from its file once.
  final Map<Sfx, Future<Duration>> _lengths = {};
  bool _contextReady = false;
  bool _foreground = true;

  /// The app can be seen: in front, or with a system sheet over it. Once
  /// it's hidden behind another app, games make no sound.
  bool _onScreen = true;

  /// The base track (menu music once the splash is done) plus anything
  /// screens have pushed on top of it (the game track during a match).
  MusicTrack _base = MusicTrack.none;
  final List<(Object, MusicTrack)> _pushed = [];
  MusicTrack _playing = MusicTrack.none;
  Timer? _fade;

  MusicTrack get _wanted {
    if (!_settings.musicOn || !_foreground) return MusicTrack.none;
    if (_pushed.isNotEmpty) return _pushed.last.$2;
    if (_base == MusicTrack.none) return MusicTrack.none;
    return _worldTrack ?? _base;
  }

  bool _ducked = false;

  /// The player has their own music on: Utopia's steps aside.
  bool _quiet = false;

  double get _musicVolume =>
      _quiet ? 0 : _settings.musicVolume * (_ducked ? 0.25 : 1);

  /// Fades Utopia's music out while the player listens to their own (and
  /// back in when they stop).
  void yieldToOtherMusic(bool on) {
    if (_quiet == on) return;
    _quiet = on;
    if (kIsWeb) {
      _guard(() => _fadeWebTo(_musicVolume, 700));
      return;
    }
    final music = _music;
    if (music == null) return;
    _guard(() => _fadeTo(music, _musicVolume, 700));
  }

  /// Turns the music down while someone's voice note plays.
  void duck(bool on) {
    if (_ducked == on) return;
    _ducked = on;
    _setMusicVolume(_musicVolume);
  }

  /// Puts the app's relaxed audio setup back after recording a voice note
  /// (the recorder switches the phone into play-and-record).
  void reclaimSession() {
    _contextReady = false;
    _guard(_ensureContext);
  }

  void updateSettings(SoundSettings settings) {
    _settings = settings;
    _syncMusic();
  }

  /// The world's own music in place of the menu's (Halloween's soundscape,
  /// the Birthday world's song), or null for the menu music.
  MusicTrack? _worldTrack;

  void setWorldTrack(MusicTrack? track) {
    if (_worldTrack == track) return;
    _worldTrack = track;
    _syncMusic();
  }

  /// Gets [effects] ready to play the moment they're wanted: in a browser,
  /// fetched and decoded now (those only some players hear, like the
  /// Winter world's, aren't fetched for everyone).
  void warm(Iterable<Sfx> effects) {
    if (!kIsWeb) return;
    for (final sfx in effects) {
      WebAudio.instance.warm(_effectAsset(sfx));
    }
  }

  /// Whether [track] is playing out loud right now.
  bool isPlaying(MusicTrack track) =>
      _playing == track && _onScreen && !_quiet && _settings.musicOn;

  /// Whether [track] is the world now showing its own sounds: its world's
  /// on screen with nothing over it (not in a game), the app's open, and
  /// Utopia isn't stepping aside for the player's own music. Unlike
  /// [isPlaying], the music needn't be on: a world's sound effects (the
  /// Halloween world's thunder and screams) play with effects on.
  bool worldShowing(MusicTrack track) =>
      _worldTrack == track &&
      _pushed.isEmpty &&
      _base != MusicTrack.none &&
      _foreground &&
      _onScreen &&
      !_quiet;

  /// One of a world's sounds, as part of its music: at the music's volume
  /// (and ducked with it) while the music's on; with the music off (and
  /// effects on), softer, as a sound effect.
  void playWithMusic(Sfx sfx, {double volume = 1}) {
    if (!_onScreen || _quiet) return;
    if (_settings.musicOn) {
      _start(sfx, _settings.musicVolume * volume * (_ducked ? 0.25 : 1));
    } else if (_settings.sfxOn) {
      _start(sfx, _settings.sfxVolume * volume * 0.5);
    }
  }

  /// [sfx] looping, fading in, until the returned loop is stopped (it
  /// fades out). Nothing with sound effects off or the app hidden.
  AmbientLoop startAmbient(Sfx sfx, {double volume = 1}) {
    if (!_onScreen || !_settings.sfxOn) return AmbientLoop(() {});
    final target = (_settings.sfxVolume * volume).clamp(0.0, 1.0).toDouble();
    if (kIsWeb) {
      final loop = WebAudio.instance.loop(_effectAsset(sfx), target);
      return AmbientLoop(loop.stop);
    }
    AudioPlayer? player;
    Timer? fade;
    var level = 0.0;
    var stopped = false;
    // Its own fades (the music's are the music's).
    void fadeTo(double to, int ms, [void Function()? then]) {
      fade?.cancel();
      final from = level;
      final steps = math.max(1, ms ~/ 40);
      var i = 0;
      fade = Timer.periodic(const Duration(milliseconds: 40), (timer) {
        i++;
        level = from + (to - from) * (i / steps);
        player?.setVolume(level.clamp(0, 1).toDouble());
        if (i >= steps) {
          timer.cancel();
          then?.call();
        }
      });
    }

    _guard(() async {
      await _ensureContext();
      if (stopped) return;
      final p = AudioPlayer();
      await p.setReleaseMode(ReleaseMode.loop);
      await p.play(AssetSource('sfx/${sfx.file}.wav'), volume: 0);
      if (stopped) {
        await p.dispose();
        return;
      }
      player = p;
      fadeTo(target, 700);
    });
    return AmbientLoop(() {
      stopped = true;
      final p = player;
      if (p == null) return;
      fadeTo(0, 300, () => p.stop().whenComplete(p.dispose));
    });
  }

  /// Vibration, from the gameplay settings. Works with sound off too.
  bool hapticsOn = true;

  void play(Sfx sfx, {double volume = 1}) {
    // On Android the app keeps running in the background, so an online
    // match carries on (moves, chat, the clock's last seconds) while the
    // player is in another app: silently, and without buzzing.
    if (!_onScreen) return;
    if (hapticsOn) _buzz(sfx);
    if (!_settings.sfxOn) return;
    _start(sfx, _settings.sfxVolume * volume);
  }

  void _start(Sfx sfx, double volume) {
    if (kIsWeb) {
      WebAudio.instance.effect(_effectAsset(sfx), volume.clamp(0, 1));
      return;
    }
    _guard(() async {
      await _ensureContext();
      final pool = await _pools.putIfAbsent(
        sfx,
        () => AudioPool.createFromAsset(
          path: 'sfx/${sfx.file}.wav',
          maxPlayers: 3,
          playerMode: PlayerMode.lowLatency,
        ),
      );
      final stop = await pool.start(volume: volume.clamp(0, 1));
      // In low-latency mode the pool never takes a player back on its own,
      // so without this every sound made a new native player that was
      // never freed, and a long session piled up thousands of them.
      final length = await _lengths.putIfAbsent(sfx, () => _clipLength(sfx));
      Timer(length + const Duration(milliseconds: 120), () {
        _guard(stop);
      });
    });
  }

  /// The length of an effect's WAV file, from its header.
  static Future<Duration> _clipLength(Sfx sfx) async {
    const fallback = Duration(seconds: 3);
    try {
      final data = await rootBundle.load('assets/sfx/${sfx.file}.wav');
      final byteRate = data.getUint32(28, Endian.little);
      // Walk the chunks after the 12-byte RIFF header to find "data".
      var at = 12;
      while (at + 8 <= data.lengthInBytes) {
        final id = String.fromCharCodes([
          for (var i = 0; i < 4; i++) data.getUint8(at + i),
        ]);
        final size = data.getUint32(at + 4, Endian.little);
        if (id == 'data' && byteRate > 0) {
          return Duration(microseconds: size * 1000000 ~/ byteRate);
        }
        at += 8 + size + (size.isOdd ? 1 : 0);
      }
    } catch (_) {}
    return fallback;
  }

  /// The buzz that goes with a sound, for the moments that deserve one.
  void _buzz(Sfx sfx) {
    final Future<void> Function()? haptic = switch (sfx) {
      Sfx.diceLand ||
      Sfx.drop ||
      Sfx.chessMove => HapticFeedback.selectionClick,
      Sfx.yourTurn ||
      Sfx.chessCapture ||
      Sfx.home => HapticFeedback.lightImpact,
      Sfx.capture ||
      Sfx.chessCheck ||
      Sfx.purchase ||
      Sfx.hwThunder1 ||
      Sfx.hwThunder2 ||
      Sfx.hwThunder3 => HapticFeedback.mediumImpact,
      Sfx.captureWar || Sfx.win || Sfx.hwScream => HapticFeedback.heavyImpact,
      _ => null,
    };
    if (haptic != null) _guard(haptic);
  }

  void setBaseTrack(MusicTrack track) {
    _base = track;
    _syncMusic();
  }

  /// Plays [track] until the returned token is passed to [popTrack].
  Object pushTrack(MusicTrack track) {
    final token = Object();
    _pushed.add((token, track));
    _syncMusic();
    return token;
  }

  void popTrack(Object token) {
    _pushed.removeWhere((entry) => entry.$1 == token);
    _syncMusic();
  }

  void _onLifecycle(AppLifecycleState state) {
    // In a browser, a window that's showing but not the one in use
    // (another app clicked) is inactive: still seen, so still heard. Only a
    // hidden tab is away.
    _foreground =
        state == AppLifecycleState.resumed ||
        (kIsWeb && state == AppLifecycleState.inactive);
    _onScreen =
        state == AppLifecycleState.resumed ||
        state == AppLifecycleState.inactive;
    _syncMusic();
  }

  void _syncMusic() {
    final wanted = _wanted;
    if (wanted == _playing) {
      _setMusicVolume(_musicVolume);
      return;
    }
    final previous = _playing;
    _playing = wanted;
    if (kIsWeb) {
      _guard(() => _syncWebMusic(previous, wanted));
      return;
    }
    _guard(() async {
      await _ensureContext();
      final music = _music ??= AudioPlayer(playerId: 'utopia-music')
        ..setReleaseMode(ReleaseMode.loop);
      if (previous != MusicTrack.none) await _fadeTo(music, 0, 350);
      if (wanted.asset == null) {
        await music.pause();
        return;
      }
      if (_playing != wanted) return; // superseded while fading out
      // Resuming the same track (back from the background) keeps its place.
      if (music.source is AssetSource &&
          (music.source! as AssetSource).path == wanted.asset) {
        await music.setVolume(0);
        await music.resume();
      } else {
        await music.setVolume(0);
        await music.play(AssetSource(wanted.asset!));
      }
      await _fadeTo(music, _musicVolume, 900);
    });
  }

  void _setMusicVolume(double volume) {
    if (kIsWeb) {
      WebAudio.instance.music.setVolume(volume);
    } else {
      _guard(() async => _music?.setVolume(volume));
    }
  }

  /// The same steps as on a phone, through the browser's music.
  Future<void> _syncWebMusic(MusicTrack previous, MusicTrack wanted) async {
    final music = WebAudio.instance.music;
    if (previous != MusicTrack.none) await _fadeWebTo(0, 350);
    if (wanted.asset == null) {
      music.pause();
      return;
    }
    if (_playing != wanted) return; // superseded while fading out
    final asset = 'assets/${wanted.asset}';
    music.setVolume(0);
    if (music.asset == asset) {
      await music.resume();
    } else {
      await music.play(asset);
    }
    await _fadeWebTo(_musicVolume, 900);
  }

  Future<void> _fadeWebTo(double target, int ms) {
    final music = WebAudio.instance.music;
    return _fadeVolume(music.volume, target, ms, music.setVolume);
  }

  Future<void> _fadeTo(AudioPlayer player, double target, int ms) =>
      _fadeVolume(
        player.volume,
        target,
        ms,
        (v) => _guard(() async => player.setVolume(v)),
      );

  Future<void> _fadeVolume(
    double start,
    double target,
    int ms,
    void Function(double volume) set,
  ) {
    _fade?.cancel();
    final done = Completer<void>();
    const stepMs = 50;
    final steps = (ms / stepMs).ceil();
    var i = 0;
    _fade = Timer.periodic(const Duration(milliseconds: stepMs), (timer) {
      i++;
      final v = start + (target - start) * (i / steps);
      set(v.clamp(0, 1).toDouble());
      if (i >= steps) {
        timer.cancel();
        if (!done.isCompleted) done.complete();
      }
    });
    return done.future;
  }

  Future<void> _ensureContext() async {
    if (_contextReady) return;
    // The Music world is listening: the microphone's play-and-record setup
    // plays everything as well, and switching away would cut it off. Put
    // back once it lets go ([reclaimSession]).
    if (RoomSound.listening) return;
    _contextReady = true;
    // Ambient on iOS: respects the silent switch and mixes with other
    // apps' audio on its own (asking for mixWithOthers as well trips the
    // plugin's check, and the first track never started in debug builds).
    await AudioPlayer.global.setAudioContext(
      AudioContext(
        iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
        android: const AudioContextAndroid(
          contentType: AndroidContentType.sonification,
          usageType: AndroidUsageType.game,
          audioFocus: AndroidAudioFocus.none,
        ),
      ),
    );
  }

  void _guard(Future<void> Function() action) {
    unawaited(
      action().catchError((Object e) {
        debugPrint('GameAudio: $e');
      }),
    );
  }

  void dispose() {
    _fade?.cancel();
    _lifecycle.dispose();
    _guard(() async => _music?.dispose());
    for (final pool in _pools.values) {
      _guard(() async => (await pool).dispose());
    }
  }
}

final gameAudioProvider = Provider<GameAudio>((ref) {
  final audio = GameAudio(ref.read(soundSettingsProvider))
    ..hapticsOn = ref.read(gameplaySettingsProvider).haptics;
  ref.listen(soundSettingsProvider, (_, next) => audio.updateSettings(next));
  ref.listen(
    gameplaySettingsProvider,
    (_, next) => audio.hapticsOn = next.haptics,
  );
  ref.onDispose(audio.dispose);
  return audio;
});

/// Plays [track] while this widget is on screen (e.g. the game music during
/// a match), then hands back to whatever was playing before.
class MusicTrackScope extends ConsumerStatefulWidget {
  const MusicTrackScope({super.key, required this.track, required this.child});

  final MusicTrack track;
  final Widget child;

  @override
  ConsumerState<MusicTrackScope> createState() => _MusicTrackScopeState();
}

class _MusicTrackScopeState extends ConsumerState<MusicTrackScope> {
  late final GameAudio _audio;
  late final Object _token;

  @override
  void initState() {
    super.initState();
    _audio = ref.read(gameAudioProvider);
    _token = _audio.pushTrack(widget.track);
  }

  @override
  void dispose() {
    _audio.popTrack(_token);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => widget.child;
}

/// A sound looping until [stop] (see [GameAudio.startAmbient]).
class AmbientLoop {
  /// A loop that [stop] ends.
  AmbientLoop(this._stop);

  final void Function() _stop;
  bool _stopped = false;

  /// Fades it out and ends it; once.
  void stop() {
    if (_stopped) return;
    _stopped = true;
    _stop();
  }
}
